window.__finlexDocLoaded(10192,{"id":10192,"articles":[{"id":1000799,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes classification of cash receipts and payments into Operating, Investing, and Financing activities, including strict rules for restricted cash (ASC 230-10-45-4) and interest/dividends.","seq":0},{"id":1000800,"no":"ASC 230-10","heading":"Cash Flow Classification & Restricted Cash Rules","text":"• Strict Classification (ASC 230-10-45): Interest paid, interest received, and dividends received are ALWAYS Operating; dividends paid are ALWAYS Financing.\n• Restricted Cash (ASU 2016-18): Beginning and ending cash totals on the Statement of Cash Flows MUST include restricted cash and restricted cash equivalents, with a reconciliation to the balance sheet.\n• Bank Overdrafts: Classified as Financing activities (not negative cash equivalents).","seq":1},{"id":1000801,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Interest & Dividends: US GAAP fixes interest paid/received and dividends received in Operating; IFRS 18 (effective 2027) classifies interest/dividends paid in Financing and interest/dividends received in Investing (for non-financial entities).\n• Bank Overdrafts: IAS 7.8 allows repayable-on-demand overdrafts to be included in cash & cash equivalents; ASC 230 treats them as Financing.","seq":2},{"id":1000802,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
